def normalize_step_decision(*,eligible,regime,routing,delegated=None,sequence=None,risk=None):
    source=(delegated or {}).get("decision") or {};ready=bool(source.get("trade_ready"));direction=source.get("developing_direction","");status="DATA UNAVAILABLE" if not eligible else "REGIME TRANSITION" if regime.get("regime") in {"TRANSITION","UNSTABLE","INSUFFICIENT_DATA"} else "RUN EXTENDED" if (sequence or {}).get("extension_state") in {"extended","extreme"} and regime.get("regime") in {"BULLISH_RUN","BEARISH_RUN"} else "RESEARCH BUY SETUP" if ready and direction=="buy" else "RESEARCH SELL SETUP" if ready and direction=="sell" else source.get("status") or {"STABLE_RANGE":"STEP RANGE","BULLISH_RUN":"WAITING FOR BUY PULLBACK","BEARISH_RUN":"WAITING FOR SELL PULLBACK","COMPRESSION":"STEP COMPRESSION","ACCEPTED_BREAKOUT":"WAITING FOR RETEST"}.get(regime.get("regime"),"NO VALID SETUP")
    return {"status":status,"market_bias":"bullish" if direction=="buy" else "bearish" if direction=="sell" else regime.get("direction","neutral"),"developing_direction":direction,"trade_ready":ready,"research_setup_available":ready,"setup_id":source.get("setup_id") if delegated else None,"summary":status.title(),"phase":regime.get("regime"),"next_action":"Review the paper research setup; no order is placed." if ready else "Do not chase the current sequence. Wait for a controlled pullback." if status=="RUN EXTENDED" else source.get("next_action") or "Wait for a validated Step structure condition.","strategy_status":"research","validated_edge":False,"paper_analysis_only":True,"confidence_ceiling":(risk or {}).get("confidence_ceiling")}
